// ── FocusAid — Görev Dağıtımı (rapor algoritması, mutlak-dakika zaman çizgisi) ──
// AI Agent sadece görev + cognitive_load üretir; planlamayı burada yaparız.
// ── scheduling-logic.js'ten kopyalandi (n8n Code node'u yerel dosya require edemez) ──
// Burada bir sey degistirirsen scheduling-logic.js'i ve testlerini de guncelle.
const LOAD_RANK = { high: 0, medium: 1, low: 2 };

function targetDayIndex(i, taskCount, dayCount) {
  if (dayCount <= 1 || taskCount <= 1) return 0;
  return Math.round(i * (dayCount - 1) / (taskCount - 1));
}

function loadRank(task) {
  const raw = task && (task.cognitiveLoad || task.cognitive_load);
  const r = LOAD_RANK[raw];
  return r === undefined ? LOAD_RANK.medium : r;
}

function orderTasksByLoad(tasks, dayCount) {
  const list = Array.isArray(tasks) ? tasks : [];
  const T = list.length;
  const groups = new Map();
  for (let i = 0; i < T; i++) {
    const targetIdx = targetDayIndex(i, T, dayCount);
    if (!groups.has(targetIdx)) groups.set(targetIdx, []);
    groups.get(targetIdx).push(i);
  }
  const out = [];
  for (const targetIdx of [...groups.keys()].sort((a, b) => a - b)) {
    const idxs = groups.get(targetIdx);
    idxs.sort((a, b) => {
      const d = loadRank(list[a]) - loadRank(list[b]);
      return d !== 0 ? d : a - b;
    });
    for (const index of idxs) out.push({ index, targetIdx });
  }
  return out;
}

function dailyCaps(taskCount, dayCount, moodDelta, hasToday) {
  const T = Math.max(0, Math.trunc(taskCount) || 0);
  const A = Math.max(1, Math.trunc(dayCount) || 1);
  const base = Math.max(1, Math.ceil(T / A));               // eski maxPerDay
  const bugunVar = hasToday === undefined ? true : !!hasToday;
  if (!moodDelta || A < 2 || !bugunVar) return { todayCap: base, restCap: base };

  // ⚠️ Tavan `base`'e (= ceil(T/A)) göre kaydırılmaz: `base` bir TAVAN, günün
  // gerçekte aldığı sayı değil. 9 görev / 4 gün planında bugüne doğal olarak 2
  // görev düşerken tavan 3'tür; 3-1=2 hiçbir şeyi değiştirmez. Ölçüldü: ilk
  // denemede `anxious` ile mod-yok planı BİREBİR aynı çıktı.
  let naturalToday = 0;
  for (let i = 0; i < T; i++) if (targetDayIndex(i, T, A) === 0) naturalToday++;

  // ⚠️ ASİMETRİ, BİLİNÇLİ: `moodDelta > 0` bugüne görev EKLEMEZ, yalnızca tavanı
  // yükseltir. Yerleştirme orantılı olduğu için tavanı büyütmek görev ÇEKMEZ;
  // çekmesi `targetDayIndex`'i oynatmayı gerektirirdi (2026-08-28 spec'inde gün
  // dağıtımı bilerek dondurulmuş). Ayrıca istenir bir şey de değil: iyi bir güne
  // fazladan iş yığmak, aynı uygulamanın hiperfokus alarmıyla korumaya çalıştığı
  // çöküşün ta kendisi. İyi modun etkisi AI prompt'unda kalır (daha iddialı,
  // daha derin görevler) — orası işin BÜYÜKLÜĞÜNÜ değiştirir, günün sayısını değil.
  const todayCap = Math.max(1, naturalToday + moodDelta);
  // ⚠️ `base` tabanı şart: bugün kapasitesini kullanmayabilir (yerleştirme
  // orantılı, açgözlü değil) ve kalan günleri eskisinden dar bırakırsak görevler
  // taşma dalına düşüp `session.start`'a ZORLANIR — üst üste binen saatler.
  // Ölçüldü: ilk denemede `hyper` çakışan etkinlik üretti.
  const restCap = Math.max(base, Math.ceil((T - todayCap) / (A - 1)));
  return { todayCap, restCap };
}
// ── kopya sonu ──
const merged = $('Merge').first().json;
const aiRaw = $json.output || '{"tasks":[]}';

let parsed;
try { parsed = JSON.parse(aiRaw); }
catch (e) { throw new Error('AI Agent gecerli JSON dondurmedi: ' + String(aiRaw).slice(0, 300)); }
const rawTasks = Array.isArray(parsed) ? parsed : (parsed.tasks || []);
if (rawTasks.length === 0) throw new Error('AI Agent hic gorev uretmedi');

const profile = merged.profile || {};
const workHours = profile.workHours || {};
const focusPeriod = profile.focusPeriod || 25;
const existingEvents = merged.existingEvents || [];

// Mola süresi (dk): profil breakStyle'a göre, yoksa 15 dk (rapor: en az 15 dk ara)
const breakMap = { pomodoro: 5, 'long-break': 15, micro: 2, free: 0 };
const breakMinutes = (profile.breakMinutes != null) ? Number(profile.breakMinutes)
  : (breakMap[profile.breakStyle] != null ? breakMap[profile.breakStyle] : 15);
const step = focusPeriod + breakMinutes;

function pad(n) { return String(n).padStart(2, '0'); }
function toMin(hhmm) { const p = String(hhmm).split(':').map(Number); return (p[0] || 0) * 60 + (p[1] || 0); }
const workStartMin = toMin(workHours.start || '09:00');
const workEndMinRaw = toMin(workHours.end || '18:00');
// Gece yarisini asan pencere (ör. 20:00 -> 06:00): bitis <= baslangic ise pencere ertesi gune tasar.
const overnight = workEndMinRaw <= workStartMin;
const sessionDuration = overnight ? (1440 - workStartMin + workEndMinRaw) : (workEndMinRaw - workStartMin);

// Istanbul (UTC+3) duvar saati — sunucu timezone'undan bağımsız
const IST = 3 * 3600 * 1000;
function wall(iso) { return new Date(new Date(iso).getTime() + IST); }

const nowW = wall(merged.now || new Date().toISOString());
const deadW = wall(merged.deadline || merged.now);

// epoch0: bugünün (yerel) gece yarısı — tüm zaman çizelgesi buradan itibaren TEK bir mutlak
// dakika sayı doğrusu olarak tutulur. Bu sayede gece-aşan pencereler ve gün sınırları ayrı
// özel-durum kodu gerektirmeden doğal biçimde çözülür.
const epoch0 = Date.UTC(nowW.getUTCFullYear(), nowW.getUTCMonth(), nowW.getUTCDate());
function absMinOf(w) { return Math.round((w.getTime() - epoch0) / 60000); }
function dateFromAbsMin(m) { return new Date(epoch0 + m * 60000); }
function dayKeyFromAbsMin(m) { const d = dateFromAbsMin(m); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()); }
function isoFromAbsMin(m) { const d = dateFromAbsMin(m); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + 'T' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':00+03:00'; }

const nowAbsMin = absMinOf(nowW);
const deadlineAbsMin = absMinOf(deadW);

// 1) scheduledSlots — mevcut takvim etkinliklerinden dolu aralıklar (mutlak dakika ekseninde)
const occ = [];
function reserve(a, b) { occ.push({ a, b }); }
function isFree(a, b) { return !occ.some(o => a < o.b && b > o.a); }
for (const ev of existingEvents) {
  const s = ev.start && (ev.start.dateTime || ev.start.date);
  const e = ev.end && (ev.end.dateTime || ev.end.date);
  if (!s || !e) continue;
  reserve(absMinOf(wall(s)), absMinOf(wall(e)));
}

// 2) Her takvim gününde bir çalışma seansı: [gün_başı + workStart, +sessionDuration).
//    Gece-aşan pencerede bu araligin sonu dogal olarak ertesi gune tasar (mutlak dakika sayesinde).
const LEAD_MIN = 15; // gorev en erken 15 dk sonra baslasin (bugunku ilk seans icin)
const sessions = [];
for (let dayOffset = 0; dayOffset <= 60; dayOffset++) {
  const sessionStartAbs = dayOffset * 1440 + workStartMin;
  if (sessionStartAbs > deadlineAbsMin) break;
  const sessionEndAbs = sessionStartAbs + sessionDuration;
  const effectiveEnd = Math.min(sessionEndAbs, deadlineAbsMin);
  const effectiveStart = dayOffset === 0 ? Math.max(sessionStartAbs, nowAbsMin + LEAD_MIN) : sessionStartAbs;
  if (effectiveStart + focusPeriod > effectiveEnd) continue; // bu seansta hic yer yok
  sessions.push({ key: dayKeyFromAbsMin(sessionStartAbs), start: effectiveStart, end: effectiveEnd, isToday: dayOffset === 0 });
}
if (sessions.length === 0) {
  const sessionStartAbs = 1440 + workStartMin; // deadline cok yakinsa/gecmisse: en azindan yarina bir seans ac
  sessions.push({ key: dayKeyFromAbsMin(sessionStartAbs), start: sessionStartAbs, end: sessionStartAbs + sessionDuration, isToday: false });
}

// 3) maxPerDay + proportional dağıtım
const T = rawTasks.length;
const A = sessions.length;

// Bugunku mod SADECE bugunun tavanini degistirir; tasan gorev SILINMEZ, sonraki
// gunlere yayilir (dailyCaps, scheduling-logic.js — gerekce ve testler orada).
// Eskiden mod yalnizca AI'ya verilen maxTasks araligini oynatiyordu ve AI araligi
// umursamadigi icin gorev sayisina hicbir etkisi olmuyordu.
const { todayCap, restCap } = dailyCaps(T, A, merged.moodDelta || 0, sessions.some(s => s.isToday));
function capFor(session) { return session.isToday ? todayCap : restCap; }

const count = {};
/** Seansin ilk bos araligi (tavani UMURSAMAZ). */
function firstFreeMinute(session) {
  for (let m = session.start; m + focusPeriod <= session.end; m += step) {
    if (isFree(m, m + focusPeriod)) return m;
  }
  return null;
}
function findSlot(session) {
  if ((count[session.key] || 0) >= capFor(session)) return null;
  return firstFreeMinute(session);
}

// Gorevler gun ICINDE bilissel yuke gore siralanir: yerlestirici "once islenen,
// o gunun en erken bos saatini alir" mantigiyla calistigi icin zor gorev gunun
// ilk seansina oturur. Gunler arasi sira degismez.
const results = [];
for (const { index: i, targetIdx } of orderTasksByLoad(rawTasks, A)) {
  const t = rawTasks[i] || {};

  let session = null, startAbs = null;
  let s = findSlot(sessions[targetIdx]);
  if (s !== null) { session = sessions[targetIdx]; startAbs = s; }
  for (let j = targetIdx + 1; session === null && j < A; j++) { const x = findSlot(sessions[j]); if (x !== null) { session = sessions[j]; startAbs = x; } }
  for (let j = targetIdx - 1; session === null && j >= 0; j--) { const x = findSlot(sessions[j]); if (x !== null) { session = sessions[j]; startAbs = x; } }
  // Tavan dolu ama SAAT bos: tavani gecici olarak yok say. Gunluk tavan bir
  // tercihtir; cakismayan takvim ise dogruluk meselesi. Tercih feda edilir.
  if (session === null) {
    for (let j = 0; j < A && session === null; j++) {
      const x = firstFreeMinute(sessions[j]);
      if (x !== null) { session = sessions[j]; startAbs = x; }
    }
  }
  // GERCEK tasma: hicbir seansta bos saat kalmadi (plan pencereye sigmiyor).
  // ⚠️ ESKIDEN burada `startAbs = session.start` vardi ve doluluk HIC kontrol
  // edilmiyordu: asiri dolu planlarda ayni saate birden cok takvim etkinligi
  // yaziliyordu (252 senaryoluk taramada 27'sinde). Artik son seansin SONUNDAN
  // itibaren ilk bos aralik araniyor — plan calisma penceresini asar, bu
  // gorunur ve durusttur; ust uste binen etkinlik ise sessiz bir veri hatasidir.
  if (session === null) {
    session = sessions[A - 1];
    startAbs = session.end;
    while (!isFree(startAbs, startAbs + focusPeriod)) startAbs += step;
  }

  reserve(startAbs, startAbs + focusPeriod);
  count[session.key] = (count[session.key] || 0) + 1;

  results.push({
    json: {
      title: t.title || t.name || ('Gorev ' + (i + 1)),
      summary: t.summary || '',
      cognitiveLoad: t.cognitiveLoad || t.cognitive_load || 'medium',
      day: session.key,
      start: isoFromAbsMin(startAbs),
      end: isoFromAbsMin(startAbs + focusPeriod),
      // Normal yerlestirmede seans sonu zaten teslimle sinirli, bu yuzden bu
      // bayrak SADECE gercek tasmada true olur: plan calisma penceresine
      // sigmadi. Respond to Webhook sayiyor, kullaniciya soyleniyor.
      deadlineAsiyor: startAbs + focusPeriod > deadlineAbsMin,
      userId: merged.userId,
      supabaseToken: merged.supabaseToken,
      googleAccessToken: merged.googleAccessToken,
      projectTitle: merged.taskTitle
    }
  });
}

// ⚠️ Bu dizinin SIRASI onemli: `Prepare Supabase Payload` node'u takvim
// olaylarini gorevlerle indeks eslesmesiyle birlestiriyor (`tasks[i]`).
// Cikti sirasini filtreleyen/degistiren bir sey eklersen orada da duzelt,
// yoksa gorevler yanlis takvim etkinligine baglanir.
return results;

// Her takvim etkinligi icin bir Supabase satiri uret.
// ONCEKI HATA: runOnceForAllItems modunda tek nesne donduruluyordu; N gorev
// parcalansa da Supabase'e yalnizca 1 kayit gidiyordu.
const events = $input.all();
const tasks  = $('Code in JavaScript').all();

return events.map((item, i) => {
  const task  = (tasks[i] || tasks[0]).json;
  const event = item.json;
  return {
    json: {
      user_id:           task.userId,
      project_title:     task.projectTitle,
      name:              task.title,
      summary:           task.summary,
      cognitive_load:    task.cognitiveLoad,
      day:               task.day,
      start_time:        task.start,
      end_time:          task.end,
      calendar_event_id: event.id,
      completed:         false
    }
  };
});
